module.render:
    const keep = String(args.space || '').trim().toLowerCase() === 'auto';
    // Blank lines around the body so its Markdown (and nested modules) render.
    return '

<div class="mdp-mod-pdfhide' + (keep ? ' mdp-pdf-keep' : '') + '">

'
      + sections.join('

').trim() + '

</div>

';
